172	/**
173	 * Where a published draft is read as a document: the blob URL a person pastes.
174	 *
175	 * Deliberately not the raw URL. A raw URL is for a program to fetch; what goes into
176	 * an issue comment is a link somebody clicks, and the blob view renders the markdown.
177	 * Measured on #12's thread against a real file on `main`.
178	 *
179	 * The path is percent-encoded per segment. A target is allowed to contain a space and
180	 * a `#`, both of which end the path in a URL — an unencoded `#` would make the link
181	 * open the branch at a fragment that does not exist, and a space is not even a legal
182	 * URL character. `encodeURIComponent` per segment rather than once over the whole
183	 * path, so the `/` separators survive.
184	 */
185	export function blobUrlFor(repo: string, branch: string, target: string): string {
186	  const path = target
187	    .split("/")
188	    .map((segment) => encodeURIComponent(segment))
189	    .join("/");
190	  return `https://github.com/${repo}/blob/${encodeURIComponent(branch)}/${path}`;
191	}
192	
193	/**
194	 * What `git update-index --index-info` is fed, in the `-z` form.
195	 *
196	 * Exported because it is the one string whose exact shape decides what lands on the
197	 * branch: a tab between the object id and the path, a NUL after each record. The `-z`
198	 * form is what makes a path with a space survive — the newline form would split it.
199	 */
200	export function indexInfoFor(entries: { blob: string; target: string }[]): string {
201	  return entries.map((entry) => `${DRAFT_FILE_MODE} blob ${entry.blob}\t${entry.target}\0`).join("");
202	}
