204	/** What one published draft resolves to before anything is pushed. */
205	export interface DraftFile {
206	  /** Absolute path of the local original, checked for readability. */
207	  source: string;
208	  /** Path on the branch, checked for the shape git accepts. */
209	  target: string;
210	}
211	
212	/**
213	 * Resolve the drafts a caller named, or say which one is unusable.
214	 *
215	 * Every refusal below is a hole that would otherwise be found after a push: a path
216	 * resolved against the wrong directory, a target that git will not accept, and two
217	 * drafts writing the same path — which would publish one file and report two.
218	 *
219	 * A relative `path` is resolved against `process.cwd()`, which is the work tree for
220	 * the same reason it is in `mcp/files.ts`: atoma starts every server as a child of the
221	 * run and inherits the directory the run was started in, which the runner starts at
222	 * the workspace root. A server started anywhere else resolves relative paths there,
223	 * and the refusal below says which directory that was rather than leaving the caller
224	 * to guess.
225	 */
226	export function resolveDraftFiles(files: { path: string; target: string }[]): DraftFile[] {
227	  const base = resolve(process.cwd());
228	  // The work tree and /tmp — the pinned interface: a draft is either a file in the
229	  // checkout or an absolute path under /tmp, which is where a conversion step puts its
230	  // output. `/tmp/atomaton-workspace` is the one subdirectory of it that survives a run.
231	  const roots = [base, TMP_ROOT];
232	  const seen = new Set<string>();
233	  const out: DraftFile[] = [];
234	
235	  for (const file of files) {
236	    const source = isAbsolute(file.path) ? resolve(file.path) : resolve(base, file.path);
237	    if (!roots.some((root) => source === root || source.startsWith(root + sep))) {
238	      throw new Error(
239	        `'${file.path}' resolves to '${source}', which is outside the places a draft may be read from ` +
240	          `(${roots.join(", ")}). Pass an absolute path, or one relative to ${base}.`,
241	      );
242	    }
243	    let size: number;
244	    try {
245	      const stats = statSync(source);
246	      if (!stats.isFile()) {
247	        throw new Error(`'${file.path}' is not a file (${source}); a draft is one file per target.`);
248	      }
249	      size = stats.size;
250	    } catch (error) {
251	      if (error instanceof Error && error.message.includes("is not a file")) throw error;
252	      throw new Error(`could not read '${file.path}': no such file at ${source}`);
253	    }
254	    if (size > MAX_READ_BYTES) {
255	      throw new Error(`${source} is ${size} bytes, past the ${MAX_READ_BYTES}-byte ceiling this tool publishes.`);
256	    }
257	    const target = normalizeTarget(file.target);
258	    if (seen.has(target)) {
259	      throw new Error(`two drafts target '${target}'; one would overwrite the other and the result would report both.`);
260	    }
261	    seen.add(target);
262	    out.push({ source, target });
263	  }
264	  return out;
265	}
266	
267	/**
268	 * The target as git will accept it, or the reason it will not.
269	 *
270	 * Checked here rather than left to `git update-index`, because git's answer to a bad
271	 * path is a warning on stderr and exit code 0 in one case (`Ignoring path /etc/x`):
272	 * the push would then succeed with the file simply absent, and the tool would report
273	 * a URL for a document that is not on the branch.
274	 */
275	function normalizeTarget(target: string): string {
276	  const trimmed = target.replace(/^\/+/, "");
277	  if (!trimmed) throw new Error("a draft's target cannot be empty.");
278	  if (isAbsolute(target) || target.startsWith("/")) {
279	    throw new Error(`target '${target}' must be relative to the branch, not absolute.`);
280	  }
281	  if (trimmed.startsWith("-")) {
282	    throw new Error(`target '${target}' starts with '-', which the index listing would read as an argument.`);
283	  }
284	  if (trimmed.includes("\\")) {
285	    throw new Error(`target '${target}' contains a backslash; branch paths are separated by '/'.`);
286	  }
287	  if (/[\t\n\r\0]/.test(trimmed)) {
288	    throw new Error(`target '${target}' contains a tab, newline or NUL, which the index listing cannot express.`);
289	  }
290	  const parts = trimmed.split("/");
291	  if (parts.some((part) => part === "" || part === "." || part === "..")) {
292	    throw new Error(`target '${target}' has an empty, '.' or '..' path segment, which git will not accept.`);
293	  }
294	  if (parts.some((part) => part.toLowerCase() === ".git")) {
295	    throw new Error(`target '${target}' is under .git, which git refuses to write a blob into.`);
296	  }
297	  return trimmed;
298	}
