332	/**
333	 * The hosts `fetch_attachment` reads.
334	 *
335	 * It is not a token guard — this tool sends no credential. It keeps a tool whose
336	 * whole job is to write a file under `/tmp` from being aimed at any host on the
337	 * internet: the caller chooses the URL, and the answer is written to disk. The two
338	 * addresses that carry a chat attachment are
339	 * `github.com/user-attachments/files/<id>/<name>` and the `private-user-images` host
340	 * a private repository's asset redirects through.
341	 */
342	export function attachmentUrlAllowed(url: URL): boolean {
343	  if (url.protocol !== "https:") return false;
344	  if (url.hostname === "github.com") return url.pathname.startsWith("/user-attachments/");
345	  return url.hostname === "private-user-images.githubusercontent.com";
346	}
