367	/**
368	 * The file to save into — the caller's name, or the URL's last segment.
369	 *
370	 * `filename` is an argument because the two names differ: an asset URL's last segment
371	 * is a generic `default.docx`, while the comment the file was attached in shows the
372	 * name the person gave it (`ペダル.docx`). `dir` is an argument for the same kind of
373	 * reason: the default is the one directory under `/tmp` that survives into the next
374	 * run on an issue, and a caller that means a different one says so.
375	 *
376	 * Nothing outside `/tmp` is written, and the refusal says why: a file inside the
377	 * checkout is this run's work and would be committed as part of it.
378	 */
379	export function attachmentPathFor(url: URL, parts: { filename?: string; dir?: string } = {}): string {
380	  const root = resolve(TMP_ROOT);
381	  const requested = parts.dir ?? ATTACHMENT_DIR;
382	  const dir = resolve(requested);
383	  if (!(dir === root || dir.startsWith(root + sep))) {
384	    throw new Error(
385	      `'${requested}' resolves to '${dir}', outside ${TMP_ROOT}. An attachment is written under ${TMP_ROOT} only: ` +
386	        "a file inside the checkout would be committed as this run's work.",
387	    );
388	  }
389	  const name = parts.filename ?? decodeSegment(url.pathname.split("/").filter(Boolean).pop() ?? "");
390	  if (!name) {
391	    throw new Error(`${url.href} names no file, so pass \`filename\` to say what to save it as.`);
392	  }
393	  if (name === "." || name === ".." || /[/\\\0]/.test(name)) {
394	    throw new Error(`'${name}' is not a file name. Pass the name alone — the directory is \`dir\`.`);
395	  }
396	  return join(dir, name);
397	}
