package attachments

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"slices"
	"strconv"
	"strings"

	"github.com/cli/cli/v2/api"
	"github.com/cli/cli/v2/internal/ghinstance"
	"github.com/cli/cli/v2/internal/safeurl"
	"github.com/cli/go-gh/v2/pkg/auth"
)

// Uploader attaches files to one upload target.
type Uploader struct {
	client           *api.Client
	host             string
	targetRepository int64
}

// NewUploader prepares uploads against targetRepository, the numeric REST id of
// the repository the assets are uploaded against, and viewerPermission, the
// GraphQL viewerPermission field on that same repository. It refuses what gh
// can tell will not upload. The credential is left to the endpoint, which
// accepts tokens from only some GitHub Apps.
//
// The host is checked first. On an enterprise server no permission makes an
// upload work, so any other order would name a fault the user cannot fix. The
// other checks are free to move.
func NewUploader(httpClient *http.Client, host string, targetRepository int64, viewerPermission string) (*Uploader, error) {
	if err := checkHost(host); err != nil {
		return nil, err
	}

	if targetRepository <= 0 {
		return nil, errors.New("could not determine which repository to attach files to")
	}

	if err := checkPermission(viewerPermission); err != nil {
		return nil, err
	}

	// TODO(api-client-rollout)
	// This line of code is part of a mechanical roll out of the api client.
	// As a follow up, consider whether the api client can be injected to this call site, rather than constructed
	return &Uploader{client: api.NewClientFromHTTP(httpClient), host: host, targetRepository: targetRepository}, nil
}

// checkHost rejects a host that cannot serve the upload endpoint. IsEnterprise
// is false for ghe.com tenants, so data residency keeps working.
func checkHost(host string) error {
	if auth.IsEnterprise(host) {
		return errors.New("attaching files is not supported on GitHub Enterprise Server")
	}
	return nil
}

// uploadPermissions lists the repository permissions that can attach a file.
// The list matches api.Repository.ViewerCanPush, and it is measured against the
// upload endpoint: READ and TRIAGE get a 404.
var uploadPermissions = []string{"ADMIN", "MAINTAIN", "WRITE"}

// checkPermission rejects a permission that cannot upload. It is an allowlist,
// so an unlisted value is rejected rather than sent.
func checkPermission(viewerPermission string) error {
	// GraphQL has no viewerPermission for a GitHub App installation, so an
	// empty one is left to the endpoint rather than refused.
	if viewerPermission == "" {
		return nil
	}

	if slices.Contains(uploadPermissions, viewerPermission) {
		return nil
	}
	return errors.New("attaching files requires write access to the repository")
}

// upload sends the file's bytes and returns the asset URL to reference
// from the markdown.
func (u *Uploader) upload(ctx context.Context, a UserAsset) (string, error) {
	assetURL, err := u.postAsset(ctx, a.getAsset())
	if err != nil {
		return "", newUploadError(err, a)
	}
	return assetURL, nil
}

// openFile is indirected so tests can stub file opening.
var openFile = func(path string) (io.ReadCloser, error) {
	return os.Open(path)
}

// postAsset does the request and reads the asset URL back. It takes the file
// rather than the UserAsset, because nothing about sending the bytes depends on
// how they render. It is separate so every way it can fail picks up the same
// explanation on the way out.
func (u *Uploader) postAsset(ctx context.Context, a asset) (string, error) {
	url, err := safeurl.JoinPathWithHostPrefix(ghinstance.UserAssetUploadPrefix(u.host), "user-attachments", "assets")
	if err != nil {
		return "", err
	}
	url.SetQuery("name", filepath.Base(a.path))
	url.SetQuery("content_type", a.contentType)
	url.SetQuery("repository_id", strconv.FormatInt(u.targetRepository, 10))

	open := func() (io.ReadCloser, error) { return openFile(a.path) }

	f, err := open()
	if err != nil {
		return "", err
	}
	defer f.Close()

	req, err := http.NewRequestWithContext(ctx, "POST", url.String(), f)
	if err != nil {
		return "", err
	}
	req.ContentLength = a.info.Size()
	req.Header.Set("Content-Type", "application/octet-stream")
	req.Header.Set("Accept", "application/vnd.github+json")
	// Without GetBody a redirect re-reads an exhausted reader.
	req.GetBody = open

	// The request is hand-built and sent with DoRequest rather than Request so
	// it can set ContentLength and GetBody, which Request cannot express.
	resp, err := u.client.DoRequest(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()

	var asset struct {
		URL string `json:"url"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&asset); err != nil {
		return "", err
	}
	if asset.URL == "" {
		return "", errors.New("the server returned no asset URL")
	}

	return asset.URL, nil
}

// newUploadError captures the status code so the message can name what the
// endpoint refused.
func newUploadError(err error, a UserAsset) error {
	uploadErr := &uploadError{Path: a.Path(), err: err}
	if httpError, ok := errors.AsType[api.HTTPError](err); ok {
		uploadErr.StatusCode = httpError.StatusCode
		uploadErr.Message = httpError.Message
		uploadErr.RetryAfter = httpError.Headers.Get("Retry-After")
	}
	return uploadErr
}

// uploadError reports a failed upload. StatusCode is zero when the request
// never reached the server.
type uploadError struct {
	Path       string
	StatusCode int
	RetryAfter string
	// Message is what the endpoint said, which api.HandleHTTPError has already
	// joined from the top level message and the per field ones.
	Message string
	err     error
}

func (e *uploadError) Error() string {
	switch e.StatusCode {
	case http.StatusNotFound:
		// The endpoint answers 404 rather than 403 when the token cannot write,
		// so the status code alone points at the wrong problem.
		return fmt.Sprintf("could not upload %s: attaching files requires write access to the repository", e.Path)
	case http.StatusUnprocessableEntity:
		if e.Message == "" {
			return fmt.Sprintf("could not upload %s", e.Path)
		}
		return fmt.Sprintf("could not upload %s: %s", e.Path, strings.ReplaceAll(e.Message, "\n", "; "))
	case http.StatusTooManyRequests:
		if e.RetryAfter == "" {
			return fmt.Sprintf("could not upload %s: rate limited; wait and try again", e.Path)
		}
		retryAfter := e.RetryAfter
		if seconds, err := strconv.Atoi(e.RetryAfter); err == nil {
			retryAfter = fmt.Sprintf("%d seconds", seconds)
		}
		return fmt.Sprintf("could not upload %s: rate limited; retry after %s", e.Path, retryAfter)
	}
	return fmt.Sprintf("failed to upload %s: %v", e.Path, e.err)
}

func (e *uploadError) Unwrap() error {
	return e.err
}

package attachments

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"

	"github.com/cli/cli/v2/internal/text"
)

// maxImageBytes is the largest image gh uploads.
const maxImageBytes int64 = 10 * 1024 * 1024

// maxVideoBytes is the largest video gh uploads. The real limit depends on the
// account plan, which gh cannot know before the request, so this is the
// generous bound and the server refuses the rest.
const maxVideoBytes int64 = 100 * 1024 * 1024

// contentTypes maps every accepted extension to the content type the endpoint
// expects, in the order gh lists them back to the user.
var contentTypes = []struct {
	ext         string
	contentType string
}{
	{".png", "image/png"},
	{".jpg", "image/jpeg"},
	{".jpeg", "image/jpeg"},
	{".gif", "image/gif"},
	{".webp", "image/webp"},
	{".svg", "image/svg+xml"},
	{".mp4", "video/mp4"},
	{".mov", "video/quicktime"},
	{".webm", "video/webm"},
}

// UserAsset is one validated local file, and everything needed to construct the
// markdown to reference it once it is uploaded.
type UserAsset interface {
	// Path is the file as the user wrote it, so a caller naming it back names
	// what they typed.
	Path() string

	rendersAsPlayer() bool
	getAsset() asset
	markdown(assetURL string) string
}

type asset struct {
	path        string
	info        fs.FileInfo
	alt         string
	contentType string
}

// imageAsset renders as a markdown image.
type imageAsset struct{ asset }

func (a *imageAsset) Path() string    { return a.asset.path }
func (a *imageAsset) getAsset() asset { return a.asset }

func (*imageAsset) rendersAsPlayer() bool { return false }

// newImageAsset applies what only holds for an image: the author may write alt
// text, and the fallback mirrors the web uploader by stripping the extension
// and replacing the remaining dots with spaces.
func newImageAsset(f asset, alt string) (UserAsset, error) {
	a := &imageAsset{f}
	if err := checkMaxSize(a.asset, maxImageBytes, "images"); err != nil {
		return nil, err
	}

	if alt == "" {
		base := filepath.Base(a.path)
		alt = strings.ReplaceAll(strings.TrimSuffix(base, filepath.Ext(base)), ".", " ")
	}
	a.alt = alt

	if err := checkAltStaysInside(a); err != nil {
		return nil, err
	}

	return a, nil
}

func (a *imageAsset) markdown(assetURL string) string {
	return fmt.Sprintf("![%s](%s)", escapeAlt(a.alt), assetURL)
}

// videoAsset renders as a player, which markdown has no syntax for: GitHub
// promotes a bare URL that is the whole content of a paragraph.
type videoAsset struct{ asset }

func (a *videoAsset) Path() string    { return a.asset.path }
func (a *videoAsset) getAsset() asset { return a.asset }

func (*videoAsset) rendersAsPlayer() bool { return true }

// newVideoAsset applies what only holds for a video: a player has no alt
// attribute to fill, so the author cannot supply one, and the name that stands
// in keeps its extension because it goes where a filename would in a link.
func newVideoAsset(f asset, alt string) (UserAsset, error) {
	a := &videoAsset{f}
	if err := checkMaxSize(a.asset, maxVideoBytes, "videos"); err != nil {
		return nil, err
	}

	if alt != "" {
		return nil, errors.New("cannot set alt text on video")
	}
	a.alt = filepath.Base(a.path)

	return a, nil
}

func (*videoAsset) markdown(assetURL string) string { return assetURL }

// newAsset validates one attached file.
func newAsset(path, alt string) (UserAsset, error) {
	fi, err := os.Stat(path)
	if err != nil {
		// Drop the syscall name so the message names the file, not the
		// operation gh performed on it.
		if pathErr, ok := errors.AsType[*fs.PathError](err); ok {
			return nil, fmt.Errorf("%s: %w", path, pathErr.Err)
		}
		return nil, err
	}

	if fi.IsDir() {
		return nil, fmt.Errorf("%s is a directory", path)
	}

	// Stat succeeds on a named pipe and Read then blocks forever.
	if !fi.Mode().IsRegular() {
		return nil, fmt.Errorf("%s is not a regular file", path)
	}

	// Nothing downstream objects to zero bytes, so an empty file uploads and
	// renders broken.
	if fi.Size() == 0 {
		return nil, fmt.Errorf("%s is empty", path)
	}

	contentType, err := supportedContentType(path)
	if err != nil {
		return nil, err
	}

	f := asset{path: path, info: fi, contentType: contentType}

	if strings.HasPrefix(contentType, "video/") {
		return newVideoAsset(f, alt)
	}
	return newImageAsset(f, alt)
}

// checkMaxSize rejects a file over the limit for its kind. The limit is
// inclusive, so the message says at most rather than under.
func checkMaxSize(a asset, maxBytes int64, kind string) error {
	if a.info.Size() <= maxBytes {
		return nil
	}
	return fmt.Errorf("%s: %s must be at most %s", a.path, kind, text.FormatSize(maxBytes))
}

// supportedContentType maps a file extension to the content type the endpoint
// expects. The extension is all gh checks, since the endpoint accepts
// mislabeled bytes anyway.
func supportedContentType(path string) (string, error) {
	ext := strings.ToLower(filepath.Ext(path))
	for _, t := range contentTypes {
		if t.ext == ext {
			return t.contentType, nil
		}
	}

	supported := make([]string, len(contentTypes))
	for i, t := range contentTypes {
		supported[i] = strings.TrimPrefix(t.ext, ".")
	}
	return "", fmt.Errorf("%s is not a supported file type (supported: %s)", path, strings.Join(supported, ", "))
}

// altEscaper neutralizes the characters that let alt text break out of the
// image syntax. Without it, alt text containing `](url)` closes the image early
// and points it somewhere the author did not choose.
var altEscaper = strings.NewReplacer(
	`\`, `\\`,
	`[`, `\[`,
	`]`, `\]`,
	"\n", " ",
	"\r", " ",
)

func escapeAlt(s string) string {
	return altEscaper.Replace(s)
}

// checkAltStaysInside renders the image this asset will produce and parses it
// back, so alt text that escapeAlt failed to neutralize is refused before the
// upload rather than discovered after it. An upload cannot be undone, which is
// why the check runs at validation.
//
// The URL is a stand-in, since the real one does not exist until the asset has
// uploaded. Only the alt text varies, so a stand-in proves the same thing.
func checkAltStaysInside(a *imageAsset) error {
	const probeURL = "https://example.invalid/probe"
	if !isSingleImage(a.markdown(probeURL), probeURL) {
		return fmt.Errorf("%s: alt text cannot be rendered safely", a.path)
	}
	return nil
}

